import React, { lazy, Suspense, useEffect, useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { Routes, Route, Navigate, Outlet, useLocation } from 'react-router-dom';
import { 
  ThemeProvider as MUIThemeProvider, 
  createTheme,
  CssBaseline,
  Box,
  Container,
  CircularProgress
} from '@mui/material';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';

// Redux
import { selectIsAuthenticated, selectAuthStatus, setCredentials } from './features/auth/authSlice';

// Auth
import { useAuth } from './context/AuthContext';

// Components
import ErrorBoundary from './components/ErrorBoundary';
import Navbar from './components/layout/Navbar';
import Footer from './components/layout/Footer';
import Alert from './components/layout/Alert';
import CommunityBuzz from './components/community/CommunityBuzz';

// Pages
import NewsHome from './pages/NewsHome';
import Login from './pages/Login';
import Register from './pages/Register';
import Dashboard from './pages/Dashboard';
import Profile from './pages/Profile';
import AdminDashboard from './pages/admin/AdminDashboard';
import Home from './pages/Home';

// Utils
import setAuthToken from './utils/setAuthToken';

// Lazy-loaded components
const WebSocketTest = lazy(() => import('./__tests__/WebSocketTest'));

// Initialize axios headers with auth token if it exists
const token = localStorage.getItem('token');
if (token) {
  setAuthToken(token);
}

// Layout component for public routes (login, register, etc.)
const PublicLayout = ({ children }) => {
  return (
    <MUIThemeProvider theme={createTheme()}>
      <LocalizationProvider dateAdapter={AdapterDateFns}>
        <CssBaseline />
        <Box
          sx={{
            display: 'flex',
            flexDirection: 'column',
            minHeight: '100vh',
            backgroundColor: '#f5f5f5',
          }}
        >
          {children}
        </Box>
      </LocalizationProvider>
    </MUIThemeProvider>
  );
};

// Layout component for private routes (dashboard, profile, etc.)
const PrivateLayout = ({ children }) => {
  const { user, loading } = useAuth();
  const location = useLocation();

  if (loading) {
    return (
      <Box 
        display="flex" 
        justifyContent="center" 
        alignItems="center" 
        minHeight="100vh"
        bgcolor="background.default"
      >
        <CircularProgress />
      </Box>
    );
  }

  if (!user) {
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
      <Navbar />
      <Container component="main" sx={{ flex: 1, py: 4, mt: 8 }}>
        <ErrorBoundary>
          <Alert />
          {children}
        </ErrorBoundary>
      </Container>
      <Footer />
    </Box>
  );
};

// Main routes configuration
const AppRoutes = () => {
  const { loading } = useAuth();
  const isAuthenticated = !!useAuth().user;

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="100vh">
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Routes>
      {/* Public routes */}
      <Route element={<PublicLayout><Outlet /></PublicLayout>}>
        <Route 
          path="login" 
          element={<Login />} 
        />
        <Route 
          path="register" 
          element={<Register />} 
        />
      </Route>
      
      {/* Protected routes */}
      <Route element={<PrivateLayout><Outlet /></PrivateLayout>}>
        <Route index element={<Navigate to="/dashboard" replace />} />
        <Route path="home" element={<Home />} />
        <Route path="news" element={<NewsHome />} />
        <Route path="community" element={<CommunityBuzz />} />
        <Route path="dashboard" element={<Dashboard />} />
        <Route path="profile" element={<Profile />} />
        <Route path="admin/*" element={<AdminDashboard />} />
        
        {process.env.NODE_ENV === 'development' && (
          <Route 
            path="ws-test" 
            element={
              <Suspense fallback={<div>Loading...</div>}>
                <WebSocketTest />
              </Suspense>
            } 
          />
        )}
        
        <Route path="*" element={<Navigate to="/dashboard" replace />} />
      </Route>
    </Routes>
  );
};

// Wrapper component to handle auth initialization
const AuthWrapper = () => {
  const { loading } = useAuth();
  
  if (loading) {
    return (
      <Box 
        display="flex" 
        justifyContent="center" 
        alignItems="center" 
        minHeight="100vh"
        bgcolor="background.default"
      >
        <CircularProgress />
      </Box>
    );
  }
  
  return <AppRoutes />;
};

function App() {
  return (
    <Suspense fallback={
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="100vh">
        <CircularProgress />
      </Box>
    }>
      <ErrorBoundary>
        <AuthWrapper />
      </ErrorBoundary>
    </Suspense>
  );
}

export default App;
